using System;
using System.Collections.Generic;
using System.Text;

namespace Relacion02_JesusCG
{
    static class Calculos
    {

        public static int RealizarOperacion(int num1, int num2, char operador)
        {
            // Recursos
            int resultado = 0;

            switch (operador)
            {
                case '+':
                    resultado = num1 + num2;
                    break;
                case '-':
                    resultado = num1 - num2;
                    break;
                case '*':
                    resultado = num1 * num2;
                    break;
                case '/':
                    resultado = num1 / num2;
                    break;
                case '%':
                    resultado = num1 % num2;
                    break;
            }
            return resultado;
        }
    }
}

namespace Relacion02_JesusCG;

public partial class Ejercicio01 : ContentPage
{
    // Enumeración para establecer el estado en el que se encuentra la aplicación
    private enum TipoEstado : byte { Operando1, Operando2 }


    // MIEMBROS DE LA CLASE
    private int _operando1;
    private int _operando2;
    private char _operador;
    private TipoEstado _estado;

    public Ejercicio01()
	{
		InitializeComponent();

        // Inicialización de los miembros
        _operando1 = 0;
        _operando2 = 0;
        _operador = '\0';
        _estado = TipoEstado.Operando1;

    }

    private void DigitosClick(object sender, EventArgs e)
    {
        // Recursos
        Button boton = (Button)sender;  // Captura del botón que genera el evento

        eVisor.Text += boton.Text;

    }

    private void OperacionClick(object sender, EventArgs e)
    {
        // Recursos
        Button boton = (Button)sender;

        try
        {
            if (String.IsNullOrEmpty(eVisor.Text))
                throw new Exception("No ha introducido operando");

            if (boton.Text != "=")
            {

                if (_estado == TipoEstado.Operando2)
                    throw new Exception("Ya ha seleccionado la operación");

                _operando1 = Convert.ToInt32(eVisor.Text);

                _operador = boton.Text[0];

                _estado = TipoEstado.Operando2;

                eVisor.Text = "";
            }
            else
            {
                if (_estado == TipoEstado.Operando1)
                    throw new Exception("No se ha establecido la operación correctamente");

                _operando2 = Convert.ToInt32(eVisor.Text);

                eVisor.Text = Calculos.RealizarOperacion(_operando1, _operando2, _operador).ToString();
            }
        }
        catch (Exception error)
        {
            DisplayAlert("Error", error.Message, "Aceptar");
            DisplayAlert("Calculadora", "Se va a reiniciar la calculadora", "Aceptar");

            eVisor.Text = "";
            _operando1 = 0;
            _operando2 = 0;
            _operador = '\0';
            _estado = TipoEstado.Operando1;
        }

    }
}

