public class Ejercicio03 : ContentPage
{
    private enum TipoEstado : byte { Operando1, Operando2 }

    // MIEMBROS DE LA CLASE
    private int _operando1;
    private int _operando2;
    private char _operador;
    private TipoEstado _estado;

    // Componentes de la Interfaz
    Entry eVisor;
    Button b1, b2, b3, b4, b5, b6, b7, b8, b9, b0;
    Button bProducto, bSuma, bDivision, bModulo, bResta, bIgual;

    // Constructor de la Clase
    public Ejercicio03()
	{
        StackLayout slPrincipal;

        // Instanciación del StackLayout de la Aplicación
        slPrincipal = new StackLayout
        {
            // Propiedades del StackLayout
            Orientation = StackOrientation.Vertical,
            Spacing = 10,
            Padding = 50,
        };

        // Instanciación de la Entrada
        eVisor = new Entry();
        // Propiedades de la Entrada
        eVisor.HorizontalOptions = LayoutOptions.Fill;
        eVisor.HorizontalTextAlignment = TextAlignment.End;
        eVisor.IsReadOnly = true;

        // Adición de la Entrada al StackLayout
        slPrincipal.Children.Add(eVisor);

        // Adición de la Primera Fila
        slPrincipal.Children.Add(Fila1Components());

        // Adición de la Segunda Fila
        slPrincipal.Children.Add(Fila2Components());

        // Adición de la Tercera Fila
        slPrincipal.Children.Add(Fila3Components());

        // Adición de la Cuarta Fila
        slPrincipal.Children.Add(Fila4Components());

        Content = slPrincipal;
    }

    /// <summary>
    /// Generación de la Primera Fila de Vistas
    /// </summary>
    /// <returns></returns>
    private StackLayout Fila1Components()
    {
        // Recursos
        StackLayout slFila;

        // Construcción del Layout
        slFila = new StackLayout
        {
            Orientation = StackOrientation.Horizontal,
            VerticalOptions = LayoutOptions.FillAndExpand,
            Spacing = 10
        };

        // Componentes del layout
        b7 = new Button
        {
            Text = "7",
            HorizontalOptions = LayoutOptions.FillAndExpand
        };
        b7.Clicked += DigitosClick;

        b8 = new Button
        {
            Text = "8",
            HorizontalOptions = LayoutOptions.FillAndExpand
        };
        b8.Clicked += DigitosClick;

        b9 = new Button
        {
            Text = "9",
            HorizontalOptions = LayoutOptions.FillAndExpand
        };
        b9.Clicked += DigitosClick;

        bProducto = new Button
        {
            Text = "*",
            HorizontalOptions = LayoutOptions.FillAndExpand
        };
        bProducto.Clicked += OperacionClick;

        // Adición de los Componentes al Layout
        slFila.Children.Add(b7);
        slFila.Children.Add(b8);
        slFila.Children.Add(b9);
        slFila.Children.Add(bProducto);

        return slFila;
    }

    /// <summary>
    /// Generación de la Segunda Fila de Vistas
    /// </summary>
    /// <returns></returns>
    private StackLayout Fila2Components()
    {
        // Recursos
        StackLayout slFila;

        // Construcción del Layout
        slFila = new StackLayout
        {
            Orientation = StackOrientation.Horizontal,
            VerticalOptions = LayoutOptions.FillAndExpand,
            Spacing = 10
        };

        // Componentes del layout
        b4 = new Button
        {
            Text = "4",
            HorizontalOptions = LayoutOptions.FillAndExpand
        };
        b4.Clicked += DigitosClick;

        b5 = new Button
        {
            Text = "5",
            HorizontalOptions = LayoutOptions.FillAndExpand
        };
        b5.Clicked += DigitosClick;

        b6 = new Button
        {
            Text = "6",
            HorizontalOptions = LayoutOptions.FillAndExpand
        };
        b6.Clicked += DigitosClick;

        bSuma = new Button
        {
            Text = "+",
            HorizontalOptions = LayoutOptions.FillAndExpand
        };
        bSuma.Clicked += OperacionClick;

        // Adición de los Componentes al Layout
        slFila.Children.Add(b4);
        slFila.Children.Add(b5);
        slFila.Children.Add(b6);
        slFila.Children.Add(bSuma);

        return slFila;
    }

    /// <summary>
    /// Generación de la Tercera Fila de Vistas
    /// </summary>
    /// <returns></returns>
    private StackLayout Fila3Components()
    {
        // Recursos
        StackLayout slFila;

        // Construcción del Layout
        slFila = new StackLayout
        {
            Orientation = StackOrientation.Horizontal,
            VerticalOptions = LayoutOptions.FillAndExpand,
            Spacing = 10
        };

        // Componentes del layout
        b1 = new Button
        {
            Text = "1",
            HorizontalOptions = LayoutOptions.FillAndExpand
        };
        b1.Clicked += DigitosClick;

        b2 = new Button
        {
            Text = "2",
            HorizontalOptions = LayoutOptions.FillAndExpand
        };
        b2.Clicked += DigitosClick;

        b3 = new Button
        {
            Text = "3",
            HorizontalOptions = LayoutOptions.FillAndExpand
        };
        b3.Clicked += DigitosClick;

        bDivision = new Button
        {
            Text = "/",
            HorizontalOptions = LayoutOptions.FillAndExpand
        };
        bDivision.Clicked += OperacionClick;

        // Adición de los Componentes al Layout
        slFila.Children.Add(b1);
        slFila.Children.Add(b2);
        slFila.Children.Add(b3);
        slFila.Children.Add(bDivision);

        return slFila;
    }

    /// <summary>
    /// Generación de la Cuarta Fila de Vistas
    /// </summary>
    /// <returns></returns>
    private StackLayout Fila4Components()
    {
        // Recursos
        StackLayout slFila;

        // Construcción del Layout
        slFila = new StackLayout
        {
            Orientation = StackOrientation.Horizontal,
            VerticalOptions = LayoutOptions.FillAndExpand,
            Spacing = 10
        };

        // Componentes del layout
        b0 = new Button
        {
            Text = "0",
            HorizontalOptions = LayoutOptions.FillAndExpand
        };
        b0.Clicked += DigitosClick;

        bModulo = new Button
        {
            Text = "%",
            HorizontalOptions = LayoutOptions.FillAndExpand
