{
    // All the code in this file is included in all platforms.
    public class MiBoton : Button
    {
        enum EstadoBoton : byte { Azul, Verde, Rojo}

        private EstadoBoton _estado;

        // CONSTRUCTORES
        public MiBoton() : base()
        {
            // Inicialización de aspectos de diseño del botón
            BackgroundColor = Colors.Blue;

            // Establecimiento de Campos propios
            _estado = EstadoBoton.Azul;

            // Suscripción de Eventos
            Clicked += MiBoton_Clicked;
        }

        public MiBoton(string texto) : this()
        {
            Text = texto;
        }

        // EVENTOS
        private void MiBoton_Clicked(object? sender, EventArgs e)
        {
            switch (_estado)
            {
                case EstadoBoton.Azul:
                    this.BackgroundColor = Colors.Green;
                    _estado = EstadoBoton.Verde;
                    break;
                case EstadoBoton.Verde:
                    BackgroundColor= Colors.Red;
                    _estado = EstadoBoton.Rojo;
                    break;
                case EstadoBoton.Rojo:
                    BackgroundColor = Colors.Blue;
                    _estado = EstadoBoton.Azul;
                    break;
            }
        }


    }
