namespace DataModelR1_JesusCG
{
    public class Usuario
    {
        // CONSTANTES
        const int TAM_MAX_NOMBRE = 20;
        const int TAM_MIN_NOMBRE = 3;

        // MIEMBROS / CAMPOS
        private string _nombre;

        // CONSTRUCTORES
        public Usuario()
        {
            // INICIALIZACIÓN DE LOS CAMPOS CON VALORES POR DEFECTO
            _nombre = null;
        }

        // PROPIEDADES (get y set)
        public string Nombre
        {
            get
            {
                // Comprobación / Validación
                if (String.IsNullOrEmpty(_nombre))
                    throw new ArgumentException("El volor del nombre no ha sido establecido");

                return _nombre;
            }

            set
            {
                // Validación / Verificación del dato de entrada

                ValidarNombre(value);

                _nombre = value;
            }
        }


        // MÉTODOS PÚBLICOS / PRIVADOS
        protected virtual void ValidarNombre(string nombre)
        {
            if (String.IsNullOrEmpty(nombre))
                throw new ArgumentNullException("No ha establecido el nombre del usuario");

            if (nombre.Length > TAM_MAX_NOMBRE)
                throw new OverflowException("La longitud del nombre ha superado el máximo de caracteres permitidos");

            if (nombre.Length < TAM_MIN_NOMBRE)
                throw new OverflowException("La longitud del nombre es inferior al mínimo de caracteres permitidos");
        }

    }
}

using System;
using System.Collections.Generic;
using System.Text;

namespace BLoginViews_JesusCG
{
    public class EntryContrasenia : Entry
    {
        // RESTRICCIONES
        const byte NUM_CARACTERES = 10;

        // CONSTRUCTORES
        public EntryContrasenia() : base()
        {
            // Establecimiento de las Propiedades por defecto
            this.IsPassword = true;

            // Establecimiento del Evento cuando pierde el foco
            Unfocused += ContraseniaUnfocused;
        }

        // PROPIEDADES

        // MANEJADORES DE EVENTOS
        private async void ContraseniaUnfocused(object sender, FocusEventArgs e)
        {
            // Recursos
            bool hayError = false;
            string mensajeError = "";

            try
            {
                // Se valida la cadena
                ValidarContrasenia(((Entry)sender).Text);

            }
            catch (Exception error)
            {
                hayError = true;
                mensajeError = error.Message;
            }
            finally
            {
                if (hayError)
                {
                    await Shell.Current.DisplayAlert("Contrasenia", mensajeError, "Aceptar");
                    ((Entry)sender).Text = "";
                    ((Entry)sender).Focus();
                }
            }
        }

        // MÉTODOS PRIVADOS
        private void ValidarContrasenia(string cadena)
        {
            // RECURSOS
            bool mayusculas = false;
            bool minusculas = false;
            bool puntuacion = false;
            bool digitos = false;

            // 1.- Comprobación de si la cadena es nula o Vacía
            if (string.IsNullOrEmpty(cadena))
                throw new ArgumentNullException("ERROR: No ha completado la contraseña");

            // 2.- Comprobar el Tamaño
            if (cadena.Length != NUM_CARACTERES)
                throw new OverflowException($"ERROR: La contraseña tiene que tener una longitud de {NUM_CARACTERES}");

            // 3.- Comprobar si contiene los diferentes caracteres
            // 3.1.- Se emplearán centinelas para controlar si se cumplen las condiciones
            foreach (char caracter in cadena)
            {
                if (Char.IsUpper(caracter))
                    mayusculas = true;
                if (Char.IsLower(caracter))
                    minusculas = true;
                if (Char.IsDigit(caracter))
                    digitos = true;
                if (Char.IsPunctuation(caracter))
                    puntuacion = true;
            }
            // 3.2.- Controlar las condiciones
            if (!mayusculas)
                throw new FormatException("ERROR: La contraseña debe contener al menos una letra mayúscula");
            if (!minusculas)
                throw new FormatException("ERROR: La contraseña debe contener al menos una letra minúscula");
            if (!digitos)
                throw new FormatException("ERROR: La contraseña debe contener al menos un dígito");
            if (!puntuacion)
                throw new FormatException("ERROR: La contraseña debe contener al menos un símbolo de puntuación");
        }
    }
}

