            // Recursos
            bool hayError = false;
            string mensajeError = "";

            try
            {
                // Se valida la cadena
                ValidarContrasenia(((Entry)sender).Text);

            }
            catch (Exception error)
            {
                hayError = true;
                mensajeError = error.Message;
            }
            finally
            {
                if (hayError)
                {
                    await Shell.Current.DisplayAlert("Contrasenia", mensajeError, "Aceptar");
                    ((Entry)sender).Text = "";
                    ((Entry)sender).Focus();
                }
            }
        }

        // MÉTODOS PRIVADOS
        private void ValidarContrasenia(string cadena)
        {
            // RECURSOS
            bool mayusculas = false;
            bool minusculas = false;
            bool puntuacion = false;
            bool digitos = false;

            // 1.- Comprobación de si la cadena es nula o Vacía
            if (string.IsNullOrEmpty(cadena))
                throw new ArgumentNullException("ERROR: No ha completado la contraseña");

            // 2.- Comprobar el Tamaño
            if (cadena.Length != NUM_CARACTERES)
                throw new OverflowException($"ERROR: La contraseña tiene que tener una longitud de {NUM_CARACTERES}");

            // 3.- Comprobar si contiene los diferentes caracteres
            // 3.1.- Se emplearán centinelas para controlar si se cumplen las condiciones
            foreach (char caracter in cadena)
            {
                if (Char.IsUpper(caracter))
                    mayusculas = true;
                if (Char.IsLower(caracter))
                    minusculas = true;
                if (Char.IsDigit(caracter))
                    digitos = true;
                if (Char.IsPunctuation(caracter))
                    puntuacion = true;
            }
            // 3.2.- Controlar las condiciones
            if (!mayusculas)
                throw new FormatException("ERROR: La contraseña debe contener al menos una letra mayúscula");
            if (!minusculas)
                throw new FormatException("ERROR: La contraseña debe contener al menos una letra minúscula");
            if (!digitos)
                throw new FormatException("ERROR: La contraseña debe contener al menos un dígito");
            if (!puntuacion)
                throw new FormatException("ERROR: La contraseña debe contener al menos un símbolo de puntuación");
        }
    }
}

