using System;
using System.Collections.Generic;
using System.Text;
using System.Text.RegularExpressions;

namespace BLoginViews_JesusCG
{
    public class EntryNombreUsuario : Entry
    {
        // RESTRICCIONES
        const byte NUM_MIN_CARACTERES = 5;
        const byte NUM_MAX_CARACTERES = 15;

        // CONSTRUCTORES
        public EntryNombreUsuario() : base()
        {
            // Establecimiento del Evento cuando pierde el foco
            Unfocused += UsuarioUnfocused;
            // MaxLength = NUM_MAX_CARACTERES;
        }

        // PROPIEDADES

        // MANEJADORES DE EVENTOS
        private async void UsuarioUnfocused(object sender, FocusEventArgs e)
        {
            // Recursos
            bool hayError = false;
            string mensajeError = "";

            try
            {
                // Se validala cadena, pero previamente se limpia de espacios en blanco
                ValidarUsuario(((Entry)sender).Text.Trim());

                // Si la cadena es válida, se sustituye en el view limpiando los caracteres
                ((Entry)sender).Text = ((Entry)sender).Text.Trim();
            }
            catch (Exception error)
            {
                hayError = true;
                mensajeError = error.Message;
            }
            finally
            {
                if (hayError)
                {
                    await Shell.Current.DisplayAlert("Usuario", mensajeError, "Aceptar");
                    ((Entry)sender).Text = "";
                    ((Entry)sender).Focus();
                }
            }
        }

        // MÉTODOS PRIVADOS
        private void ValidarUsuario(string cadena)
        {
            // RECURSOS
            Regex formato;

            // 1.- Comprobación de si la cadena es nula o Vacía
            if (string.IsNullOrEmpty(cadena))
                throw new ArgumentNullException("ERROR: No ha completado el nombre del usuario");
            // 2.- Limpiar la cadena de espacios en blanco al principio y al final
            //cadena = cadena.Trim();

            // 3.- Comprobar el Tamaño
            if ((cadena.Length > NUM_MAX_CARACTERES) || (cadena.Length < NUM_MIN_CARACTERES))
                throw new OverflowException($"ERROR: El identificador del usuario tiene que tener entre {NUM_MIN_CARACTERES} y {NUM_MAX_CARACTERES} caracteres");

            // 4.- Comprobar Caracteres Correctos (No Caracteres Especiales) 
            formato = new Regex(@"[A-Z]*");
            if (!formato.IsMatch(cadena.ToUpper()))
            {
                throw new FormatException("ERROR: El nombre del usuario contiene caracteres incorrectos");
            }
        }
    }
}

